 size_t answers=0,invalid=0,nonanswers=0,failures=0,expected=0,arithmetic_pairs=0;bool stage_count_gate=fixtures_only,answer_count_gate=fixtures_only,fixture_count_gate=fixtures_only,arithmetic_match_gate=fixtures_only;
