    require(j.at("schema").scalar=="n83-rho-speed-evaluation/v1","Unexpected producer schema");check_modulus(j);require(num(j.at("n"))==83&&num(j.at("a"))==1&&num(j.at("b"))==1&&num(j.at("subgroup_order"))==instance.r&&num(j.at("lambda"))==instance.lambda&&point(j.at("generator"))==instance.g,"Producer exact curve/G/r/lambda mismatch");
